import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

/**
 * @kind path-problem
 * @problem.severity high
 * @name Path traversal in file operations
 * @description User input reaching file operations without proper validation can lead to path traversal
 * @tags security
 * @id py/path-traversal
 */

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Match open() calls
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Match file operations
      call = API::moduleImport("os").getMember(["open", "remove", "rename", "stat", "chmod", "chown", "utime", "link", "symlink", "readlink", "mknod", "mkdir", "rmdir", "listdir"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Match pathlib operations
      call = API::moduleImport("pathlib").getMember(["Path"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Dangerous deserialization with user input flow
 * @description Check if user input flows to dangerous deserialization operations
 * @kind path-problem
 * @problem.severity high
 * @id py/dangerous-deserialization-flow
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Match pickle operations
      call = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Match yaml operations  
      call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Match marshal operations
      call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Match shelve operations
      call = API::moduleImport("shelve").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Match json.load/loads - could still be problematic with custom object_hook
      call = API::moduleImport("json").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module DeserializationFlow = TaintTracking::Global<DeserializationConfig>;
import DeserializationFlow::PathGraph

from DeserializationFlow::PathNode source, DeserializationFlow::PathNode sink
where DeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dangerous deserialization from $@.", source.getNode(), "user input"

